Based on the commit message, the root cause and the patch provided below, you need to:

1. explain how the bug occurs, including all code statements that are most likely to lead to the bug and why. 
2. explain how the bug is fixed, including code statements fixing the bug and why. 

You must include one or more code statements in point 1 and 2.
Code statements included in point 1 should be as brief as possible, only include the ones that are most related to the root cause and  the number of code statements may not exceed 3.


Here is the commit message:
wifi: mt76: mt7921: fix a potential clc buffer length
 underflow

The buf_len is used to limit the iterations for retrieving the country
power setting and may underflow under certain conditions due to changes
in the power table in CLC.

This underflow leads to an almost infinite loop or an invalid power
setting resulting in driver initialization failure.

Cc: stable@vger.kernel.org
Fixes: fa6ad88e023d ("wifi: mt76: mt7921: fix country count limitation for CLC")
Signed-off-by: Leon Yen <leon.yen@mediatek.com>
Signed-off-by: Ming Yen Hsieh <mingyen.hsieh@mediatek.com>
Link: https://patch.msgid.link/20251009020158.1923429-1-mingyen.hsieh@mediatek.com
Signed-off-by: Felix Fietkau <nbd@nbd.name>

Here is the root cause:
The `buf_len` variable, used to limit iterations over country power table entries, is decremented by the size of each rule (`offset`) without first checking if `buf_len` is smaller than `offset`. When the power table format changes (e.g., in CLC data), `buf_len` can become less than `offset`, causing an unsigned underflow (or negative value) that results in an almost infinite loop or invalid memory access, leading to driver initialization failure.

Here is the patch:

 static
 int __mt7921_mcu_set_clc(struct mt792x_dev *dev, u8 *alpha2,
 			 enum environment_cap env_cap,
 			 struct mt7921_clc *clc,
 			 u8 idx)
 {
 #define CLC_CAP_EVT_EN BIT(0)
 #define CLC_CAP_DTS_EN BIT(1)
 	struct sk_buff *skb, *ret_skb = NULL;
 	struct {
 		u8 ver;
 		u8 pad0;
 		__le16 len;
 		u8 idx;
 		u8 env;
 		u8 acpi_conf;
 		u8 cap;
 		u8 alpha2[2];
 		u8 type[2];
 		u8 env_6g;
 		u8 mtcl_conf;
 		u8 rsvd[62];
 	} __packed req = {
 		.ver = 1,
 		.idx = idx,
 		.env = env_cap,
 		.env_6g = dev->phy.power_type,
 		.acpi_conf = mt792x_acpi_get_flags(&dev->phy),
 		.mtcl_conf = mt792x_acpi_get_mtcl_conf(&dev->phy, alpha2),
 	};
 	int ret, valid_cnt = 0;
 	u32 buf_len = 0;
 	u8 *pos;

 	if (!clc)
 		return 0;

 	if (dev->phy.chip_cap & MT792x_CHIP_CAP_CLC_EVT_EN)
 		req.cap |= CLC_CAP_EVT_EN;
 	if (mt76_find_power_limits_node(&dev->mt76))
 		req.cap |= CLC_CAP_DTS_EN;

 	buf_len = le32_to_cpu(clc->len) - sizeof(*clc);
 	pos = clc->data;
 	while (buf_len > 16) {
 		struct mt7921_clc_rule *rule = (struct mt7921_clc_rule *)pos;
 		u16 len = le16_to_cpu(rule->len);
 		u16 offset = len + sizeof(*rule);

+		if (buf_len < offset)
+			break;
+
 		pos += offset;
 		buf_len -= offset;
 		if (rule->alpha2[0] != alpha2[0] ||
 		    rule->alpha2[1] != alpha2[1])
 			continue;

 		memcpy(req.alpha2, rule->alpha2, 2);
 		memcpy(req.type, rule->type, 2);

 		req.len = cpu_to_le16(sizeof(req) + len);
 		skb = __mt76_mcu_msg_alloc(&dev->mt76, &req,
 					   le16_to_cpu(req.len),
 					   sizeof(req), GFP_KERNEL);
 		if (!skb)
 			return -ENOMEM;
 		skb_put_data(skb, rule->data, len);

 		ret = mt76_mcu_skb_send_and_get_msg(&dev->mt76, skb,
 						    MCU_CE_CMD(SET_CLC),
 						    !!(req.cap & CLC_CAP_EVT_EN),
 						    &ret_skb);
 		if (ret < 0)
 			return ret;

 		if (ret_skb) {
 			struct mt7921_clc_info_tlv *info;

 			info = (struct mt7921_clc_info_tlv *)(ret_skb->data + 4);
 			dev->phy.clc_chan_conf = info->chan_conf;
 			dev_kfree_skb(ret_skb);
 		}

 		valid_cnt++;
 	}

 	if (!valid_cnt)
 		return -ENOENT;

 	return 0;
 }



